// Imitate its imports, assertion style and conventions. Do not modify it.
package org.json;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class JSONObjectMacMutTest {

    static class SimpleBean {
        public String value = "expected";
    }

    @Test
    public void testNonRecordBeanToJson() {
        JSONObject jo = new JSONObject(new SimpleBean());
        assertTrue(jo.has("value"));
        assertEquals("expected", jo.getString("value"));
    }
}
